(function(){'use strict';
const Q=["Oh wow, another day of doing nothing. Truly inspiring. The job market must be fighting over you.", "You keep \"taking breaks\" like you\u2019ve actually done something to deserve one. Bold strategy.", "It\u2019s adorable how you talk about your dreams with the work ethic of a side character.", "You say you\u2019re stressed, but from what exactly? The Olympic-level scrolling?", "At this point, your biggest achievement this year is avoiding studying. Congrats, I guess.", "You\u2019ve wasted so much time this year you should honestly add it to your CV - it\u2019s the only thing you\u2019re good at.", "Success isn\u2019t avoiding you. It just doesn\u2019t recognise you as someone worth visiting."],V=["data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,"];
const FRAMES=["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"];

const READ=25000,TURN=2000,BACK=2000,MIN_LOOK=14000;
let epoch=performance.now(),last=epoch,x=12,dir=1,permission=false,on=true,spoken=-1,page='',cycle=0,phase='read',lookMs=MIN_LOOK;
try{on=localStorage.getItem('conquer-penguin-sound')!=='off'}catch(e){}
const audio=new Audio();audio.preload='auto';audio.playbackRate=.85;audio.preservesPitch=true;
function unlock(){permission=true}
function stopVoice(){audio.pause()}
function restart(){epoch=performance.now();last=epoch;phase='read';lookMs=MIN_LOOK;audio.pause()}
function activate(id){if(page!==id){page=id;restart()}}
function state(){const now=performance.now();let elapsed=now-epoch;
if(phase==='read'&&elapsed>=READ){phase='turn';epoch+=READ;elapsed=now-epoch}
if(phase==='turn'&&elapsed>=TURN){phase='look';epoch+=TURN;elapsed=now-epoch}
if(phase==='look'&&elapsed>=lookMs&&audio.paused){phase='turnback';epoch=now;elapsed=0}
if(phase==='turnback'&&elapsed>=BACK){phase='read';epoch=now;elapsed=0;cycle++;spoken=-1;lookMs=MIN_LOOK}
const dt=Math.max(0,Math.min(100,now-last))/1000;last=now;
if(phase==='read'&&!document.hidden){const max=Math.max(12,innerWidth-300);x+=dir*10*dt;if(x>=max){x=max;dir=-1}if(x<=12){x=12;dir=1}}
const frame=phase==='read'?Math.floor(elapsed/650)%6:phase==='turn'?(elapsed<TURN/2?6:7):phase==='look'?7:(elapsed<BACK/2?7:6);
return {phase,frame,cycle,elapsed,readMs:READ,x,dir};}
function present(n){if(spoken===n)return;spoken=n;if(!permission||!on)return;
try{audio.pause();audio.src=V[n%7];audio.currentTime=0;audio.playbackRate=.85;audio.onloadedmetadata=function(){if(Number.isFinite(audio.duration))lookMs=Math.max(MIN_LOOK,audio.duration/.85*1000+1500)};audio.play().catch(function(){})}catch(e){}}
function toggle(){on=!on;unlock();if(!on)audio.pause();else if(phase==='look'){spoken=-1;present(cycle)}try{localStorage.setItem('conquer-penguin-sound',on?'on':'off')}catch(e){}return on}
window.ConquerPenguinMotion={frames:FRAMES,state,activate,quote:n=>Q[n%7],present,stopVoice,restart,toggle,unlock,muted:()=>!on,info:()=>({readMs:READ,turnMs:TURN,lookMs,backMs:BACK,speed:10,frameMs:650,voices:7})};
window.ConquerPenguinVoice={stop:stopVoice,toggle,muted:()=>!on,unlock,info:()=>({voices:7,on}),speaking:()=>!audio.paused};
document.addEventListener('pointerdown',unlock);document.addEventListener('keydown',unlock);
document.addEventListener('visibilitychange',restart);
})();